def get_page(title, content=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get-page"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        ts = _now_iso()
        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta:
            row["meta"] = meta
        if error:
            row["error"] = error
        logs.append(row)
        _save(chosen, logs)

    # Validate inputs
    if not isinstance(title, str) or not title.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "title is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if content is None:
        content = "noContent"
    if not isinstance(content, str) or content not in ("noContent", "withSource", "withHtml"):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "content must be one of: noContent, withSource, withHtml"})
        return _err("VALIDATION_ERROR", "content must be one of: noContent, withSource, withHtml")

    # Resolve an active session / wiki context that actually has the page
    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    revisions = _load("revisions.json")
    if not isinstance(revisions, list):
        revisions = []
    title_q = title.strip()

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url")]
    # Prefer session(s) whose wiki has the page
    chosen_session = None
    chosen_page = None
    for s in active_sessions:
        wbu = s.get("wiki_base_url")
        for p in pages:
            if isinstance(p, dict) and p.get("wiki_base_url") == wbu and p.get("prefixed_title") == title_q:
                chosen_session = s
                chosen_page = p
                break
        if chosen_page:
            break

    # Fallback: allow resolution without session by searching any wiki (to avoid refusing well-formed requests)
    if chosen_page is None:
        for p in pages:
            if isinstance(p, dict) and p.get("prefixed_title") == title_q:
                chosen_page = p
                # choose any active session for that wiki if present
                for s in active_sessions:
                    if s.get("wiki_base_url") == p.get("wiki_base_url"):
                        chosen_session = s
                        break
                break

    if chosen_page is None:
        _append_request_log("ok", session_id=chosen_session.get("id") if chosen_session else None, wiki_base_url=chosen_session.get("wiki_base_url") if chosen_session else None, meta={"result": "empty"})
        return {"page": None}

    # Deletion semantics: redacted/not found
    if chosen_page.get("status") == "deleted":
        _append_request_log("error", session_id=chosen_session.get("id") if chosen_session else None, wiki_base_url=chosen_page.get("wiki_base_url"), error={"code": "NOT_FOUND", "message": "Page not found"})
        return _err("NOT_FOUND", "Page not found")

    # Latest revision metadata (must be included if possible)
    latest_rev = None
    if chosen_page.get("latest_revision_id"):
        for r in revisions:
            if isinstance(r, dict) and r.get("id") == chosen_page.get("latest_revision_id"):
                # FK integrity: revision must belong to same page
                if r.get("page_id") == chosen_page.get("id"):
                    latest_rev = r
                break

    # Build response page object
    page_obj = {
        "id": chosen_page.get("id"),
        "wiki_base_url": chosen_page.get("wiki_base_url"),
        "namespace": chosen_page.get("namespace"),
        "title": chosen_page.get("title"),
        "prefixed_title": chosen_page.get("prefixed_title"),
        "content_model": chosen_page.get("content_model"),
        "status": chosen_page.get("status"),
        "license_code": chosen_page.get("license_code"),
        "license_url": chosen_page.get("license_url"),
        "latest_revision": None,
        "created_at": chosen_page.get("created_at"),
        "updated_at": chosen_page.get("updated_at"),
    }

    if latest_rev:
        page_obj["latest_revision"] = {
            "id": latest_rev.get("id"),
            "revision_number": latest_rev.get("revision_number"),
            "parent_revision_number": latest_rev.get("parent_revision_number"),
            "status": latest_rev.get("status"),
            "comment": latest_rev.get("comment"),
            "tags": latest_rev.get("tags"),
            "created_at": latest_rev.get("created_at"),
            "updated_at": latest_rev.get("updated_at"),
            "content_model": latest_rev.get("content_model"),
        }
        # Ensure page.latest_revision_number reflects revision row if inconsistent
        page_obj["latest_revision_number"] = chosen_page.get("latest_revision_number", latest_rev.get("revision_number"))
    else:
        page_obj["latest_revision_number"] = chosen_page.get("latest_revision_number")

    # Optionally include content
    if content == "withSource":
        if latest_rev:
            page_obj["source_text"] = latest_rev.get("source_text")
        else:
            page_obj["source_text"] = None
    elif content == "withHtml":
        # Serve cache only if it matches latest revision id; otherwise generate and update atomically.
        latest_id = chosen_page.get("latest_revision_id")
        if latest_id and chosen_page.get("rendered_html_cache") is not None and chosen_page.get("rendered_html_revision_id") == latest_id:
            page_obj["html"] = chosen_page.get("rendered_html_cache")
        else:
            # Generate simple HTML (offline) from source_text; update cache with revision id if possible.
            src = latest_rev.get("source_text") if latest_rev else ""
            # minimal safe rendering; real MW is complex; we still must update cache observably
            def _escape(s):
                return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))
            html = "<pre>" + _escape(src or "") + "</pre>"
            page_obj["html"] = html
            # Atomic-ish update: reload pages file, find row, write cache fields
            pages2 = _load("pages.json")
            if isinstance(pages2, list) and latest_id:
                updated = False
                now = _now_iso()
                for p2 in pages2:
                    if isinstance(p2, dict) and p2.get("id") == chosen_page.get("id"):
                        p2["rendered_html_cache"] = html
                        p2["rendered_html_revision_id"] = latest_id
                        p2["updated_at"] = now
                        updated = True
                        break
                if updated:
                    _save("pages.json", pages2)
                    # reflect updated fields
                    chosen_page["rendered_html_cache"] = html
                    chosen_page["rendered_html_revision_id"] = latest_id
                    chosen_page["updated_at"] = now

    # Touch session last_used_at if we have one
    if chosen_session and chosen_session.get("id"):
        sessions2 = _load("wiki_sessions.json")
        if isinstance(sessions2, list):
            now = _now_iso()
            for s2 in sessions2:
                if isinstance(s2, dict) and s2.get("id") == chosen_session.get("id"):
                    s2["last_used_at"] = now
                    s2["updated_at"] = now
                    break
            _save("wiki_sessions.json", sessions2)

    _append_request_log("ok", session_id=chosen_session.get("id") if chosen_session else None, wiki_base_url=chosen_page.get("wiki_base_url"))
    return {"page": page_obj}

def get_page_history(title, olderThan=None, newerThan=None, filter=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get-page-history"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        ts = _now_iso()
        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta:
            row["meta"] = meta
        if error:
            row["error"] = error
        logs.append(row)
        _save(chosen, logs)

    # Validate inputs
    if not isinstance(title, str) or not title.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "title is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if olderThan is not None and not isinstance(olderThan, (int, float)):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "olderThan must be a number when provided"})
        return _err("VALIDATION_ERROR", "olderThan must be a number when provided")
    if newerThan is not None and not isinstance(newerThan, (int, float)):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "newerThan must be a number when provided"})
        return _err("VALIDATION_ERROR", "newerThan must be a number when provided")
    if olderThan is not None and newerThan is not None:
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "olderThan and newerThan cannot both be provided"})
        return _err("VALIDATION_ERROR", "olderThan and newerThan cannot both be provided")
    if filter is not None and not isinstance(filter, str):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "filter must be a string when provided"})
        return _err("VALIDATION_ERROR", "filter must be a string when provided")
    if isinstance(filter, str) and filter.strip() == "":
        filter = None

    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    revisions = _load("revisions.json")
    if not isinstance(revisions, list):
        revisions = []
    title_q = title.strip()

    # Resolve context and page similarly to get-page: prefer active session wiki that contains page
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url")]
    chosen_session = None
    chosen_page = None
    for s in active_sessions:
        wbu = s.get("wiki_base_url")
        for p in pages:
            if isinstance(p, dict) and p.get("wiki_base_url") == wbu and p.get("prefixed_title") == title_q:
                chosen_session = s
                chosen_page = p
                break
        if chosen_page:
            break
    if chosen_page is None:
        for p in pages:
            if isinstance(p, dict) and p.get("prefixed_title") == title_q:
                chosen_page = p
                for s in active_sessions:
                    if s.get("wiki_base_url") == p.get("wiki_base_url"):
                        chosen_session = s
                        break
                break

    if chosen_page is None:
        _append_request_log("ok", session_id=chosen_session.get("id") if chosen_session else None, meta={"total": 0})
        return {"revisions": [], "meta": {"total": 0, "limit": 20, "has_more": False, "next_older_than": None, "next_newer_than": None}}

    if chosen_page.get("status") == "deleted":
        _append_request_log("error", session_id=chosen_session.get("id") if chosen_session else None, wiki_base_url=chosen_page.get("wiki_base_url"), error={"code": "NOT_FOUND", "message": "Page not found"})
        return _err("NOT_FOUND", "Page not found")

    # Collect revisions for this page
    page_id = chosen_page.get("id")
    page_revs = [r for r in revisions if isinstance(r, dict) and r.get("page_id") == page_id]
    # Optional tag filter: exactly one tag string (tool provides one string)
    if filter is not None:
        tag = filter.strip()
        page_revs = [r for r in page_revs if isinstance(r.get("tags"), list) and tag in r.get("tags")]

    # Apply older/newer than on revision_number
    if olderThan is not None:
        page_revs = [r for r in page_revs if isinstance(r.get("revision_number"), (int, float)) and r.get("revision_number") < float(olderThan)]
    if newerThan is not None:
        page_revs = [r for r in page_revs if isinstance(r.get("revision_number"), (int, float)) and r.get("revision_number") > float(newerThan)]

    # Sort newest-first by revision_number
    def _revnum(r):
        v = r.get("revision_number")
        return v if isinstance(v, (int, float)) else -1
    page_revs.sort(key=_revnum, reverse=True)

    limit = 20
    segment = page_revs[:limit]
    has_more = len(page_revs) > limit
    next_older_than = None
    next_newer_than = None
    if segment:
        # For older paging, pass smallest revnum in returned segment
        nums = [float(r.get("revision_number")) for r in segment if isinstance(r.get("revision_number"), (int, float))]
        if nums:
            next_older_than = min(nums)
            next_newer_than = max(nums)

    out_revs = []
    for r in segment:
        out_revs.append({
            "id": r.get("id"),
            "revision_number": r.get("revision_number"),
            "parent_revision_number": r.get("parent_revision_number"),
            "status": r.get("status"),
            "comment": r.get("comment"),
            "tags": r.get("tags"),
            "content_model": r.get("content_model"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    # Touch session
    if chosen_session and chosen_session.get("id"):
        sessions2 = _load("wiki_sessions.json")
        if isinstance(sessions2, list):
            now = _now_iso()
            for s2 in sessions2:
                if isinstance(s2, dict) and s2.get("id") == chosen_session.get("id"):
                    s2["last_used_at"] = now
                    s2["updated_at"] = now
                    break
            _save("wiki_sessions.json", sessions2)

    _append_request_log("ok", session_id=chosen_session.get("id") if chosen_session else None, wiki_base_url=chosen_page.get("wiki_base_url"), meta={"total": len(page_revs), "returned": len(out_revs)})
    return {
        "revisions": out_revs,
        "meta": {
            "total": len(page_revs),
            "limit": limit,
            "has_more": has_more,
            "next_older_than": next_older_than if has_more else None,
            "next_newer_than": next_newer_than if has_more else None,
        },
    }

def search_page(query, limit=None, **_extra):
    import json, os, datetime, time, re, uuid
    from urllib.parse import urlparse, urlunparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if isinstance(s, str) and s:
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _normalize_base(url):
        p = urlparse(url)
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        host = p.hostname.lower() if p.hostname else ""
        if not host:
            return None
        netloc = host
        if p.port:
            netloc = f"{host}:{p.port}"
        path = p.path or ""
        path = re.sub(r"/+$", "", path)
        return urlunparse((p.scheme, netloc, path, "", "", ""))

    def _pick_active_session(sessions):
        active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        if not active:
            return None
        def key(s):
            dt = _parse_dt(s.get("last_used_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        active.sort(key=key, reverse=True)
        return active[0]

    t0 = time.time()
    sessions = _load("wiki_sessions.json")
    pages = _load("pages.json")
    search_queries = _load("search_queries.json")

    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()

    if limit is None:
        limit_val = 20
    else:
        if not isinstance(limit, (int, float)):
            return _err("VALIDATION_ERROR", "limit must be a number")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100 inclusive")
        limit_val = int(limit)

    sess = _pick_active_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No active wiki session. Call set-wiki first.")
    wiki_base = sess.get("wiki_base_url")
    if not isinstance(wiki_base, str) or not _normalize_base(wiki_base):
        return _err("UNAUTHORIZED", "Active session has no valid wiki selected. Call set-wiki first.")

    # Record query row (queued -> completed in same call for offline backend)
    now = _now_iso()
    sq_id = f"sq_{uuid.uuid4().hex}"
    sq_row = {
        "id": sq_id,
        "wiki_base_url": wiki_base,
        "query": q,
        "limit": limit_val,
        "status": "queued",
        "result_page_ids": [],
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    search_queries.append(sq_row)

    # Update session last_used
    sess["last_used_at"] = now
    sess["updated_at"] = now
    _save("wiki_sessions.json", sessions)

    # Basic local search over titles and optional search_vector/title tokens
    ql = q.lower()
    def page_score(p):
        pt = (p.get("prefixed_title") or "").lower()
        t = (p.get("title") or "").lower()
        score = 0
        if ql in pt:
            score += 10
        if ql in t:
            score += 6
        # Optional search_vector tokens
        sv = p.get("search_vector")
        if isinstance(sv, dict):
            tokens = sv.get("tokens")
            if isinstance(tokens, list):
                if any(isinstance(tok, str) and ql in tok.lower() for tok in tokens):
                    score += 2
        return score

    candidates = []
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("wiki_base_url") != wiki_base:
            continue
        if p.get("status") == "deleted":
            continue
        if page_score(p) > 0:
            candidates.append(p)

    candidates.sort(key=lambda p: (page_score(p), (p.get("prefixed_title") or "")), reverse=True)
    results = candidates[:limit_val]

    sq_row["result_page_ids"] = [p.get("id") for p in results if p.get("id") is not None]
    sq_row["status"] = "completed"
    sq_row["updated_at"] = _now_iso()

    _save("search_queries.json", search_queries)

    # Return pages referenced by result_page_ids (in order)
    id_to_page = {p.get("id"): p for p in pages if isinstance(p, dict)}
    out_pages = []
    for pid in sq_row["result_page_ids"]:
        p = id_to_page.get(pid)
        if p and p.get("wiki_base_url") == wiki_base and p.get("status") != "deleted":
            out_pages.append({
                "id": p.get("id"),
                "prefixed_title": p.get("prefixed_title"),
                "title": p.get("title"),
                "namespace": p.get("namespace"),
                "content_model": p.get("content_model"),
                "status": p.get("status"),
                "latest_revision_number": p.get("latest_revision_number"),
                "license_code": p.get("license_code"),
                "license_url": p.get("license_url"),
                "updated_at": p.get("updated_at"),
            })

    return {
        "search": {
            "id": sq_id,
            "wiki_base_url": wiki_base,
            "query": q,
            "limit": limit_val,
            "status": sq_row["status"],
            "created_at": sq_row["created_at"],
            "updated_at": sq_row["updated_at"],
        },
        "pages": out_pages,
        "meta": {
            "returned": len(out_pages),
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def set_wiki(wikiUrl, **_extra):
    import json, os, datetime, time, re, hashlib
    from urllib.parse import urlparse, urlunparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "set-wiki"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, error_code=None, error_message=None, session_id=None, wiki_base_url=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        ts = _now_iso()
        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(chosen, logs)

    # Validate: accept either a real URL or (per audit) a session id that already exists.
    if not isinstance(wikiUrl, str) or not wikiUrl.strip():
        _append_request_log("error", "VALIDATION_ERROR", "wikiUrl must be a non-empty string")
        return _err("VALIDATION_ERROR", "wikiUrl must be a non-empty string")
    wikiUrl = wikiUrl.strip()

    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # If wikiUrl matches an existing session id, treat as selecting that session's already-resolved wiki.
    matched_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == wikiUrl:
            matched_session = s
            break
    if matched_session:
        # Ensure it's usable; if expired/revoked, conflict with intended selection semantics.
        if matched_session.get("status") != "active":
            _append_request_log("error", "CONFLICT", "Session is not active", session_id=matched_session.get("id"))
            return _err("CONFLICT", "Session is not active")
        now_iso = _now_iso()
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == matched_session.get("id"):
                s["last_used_at"] = now_iso
                s["updated_at"] = now_iso
                matched_session = s
                break
        _save("wiki_sessions.json", sessions)
        _append_request_log("ok", session_id=matched_session.get("id"), wiki_base_url=matched_session.get("wiki_base_url"), meta={"mode": "bySessionId"})
        return {"session": matched_session}

    # Otherwise parse as URI
    try:
        p = urlparse(wikiUrl)
    except Exception:
        _append_request_log("error", "VALIDATION_ERROR", "wikiUrl must be a valid URI")
        return _err("VALIDATION_ERROR", "wikiUrl must be a valid URI")
    if p.scheme not in ("http", "https") or not p.netloc:
        _append_request_log("error", "VALIDATION_ERROR", "wikiUrl must be a valid absolute URI (http/https)")
        return _err("VALIDATION_ERROR", "wikiUrl must be a valid absolute URI (http/https)")

    host = (p.hostname or "").lower()
    if not host:
        _append_request_log("error", "VALIDATION_ERROR", "wikiUrl must include a host")
        return _err("VALIDATION_ERROR", "wikiUrl must include a host")
    netloc = host + (f":{p.port}" if p.port else "")

    # Normalize base: remove trailing slash unless root; keep any path prefix (e.g. /wikis/foo)
    path = p.path or ""
    path = re.sub(r"/+$", "", path)
    wiki_base_url = urlunparse((p.scheme, netloc, path, "", "", ""))

    # Derive endpoints (allow overrides but follow typical installation)
    # If path ends with /wiki/... then base is prior to /wiki
    if "/wiki/" in path:
        base_path = path.split("/wiki/")[0]
        wiki_base_url = urlunparse((p.scheme, netloc, re.sub(r"/+$", "", base_path), "", "", ""))
    if wiki_base_url.endswith("/"):
        wiki_base_url = wiki_base_url[:-1]

    # Article path heuristics
    article_path = "/wiki/$1"
    if "/en-US/docs/" in (p.path or ""):
        article_path = "/en-US/docs/$1"
    elif "/wiki/" in (p.path or ""):
        article_path = "/wiki/$1"

    api_endpoint = wiki_base_url + "/w/api.php"
    rest_endpoint = wiki_base_url + "/api/rest_v1"

    # Choose an existing active session to update; otherwise pick any active that can be used, else unauthorized.
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active:
        _append_request_log("error", "UNAUTHORIZED", "No active wiki session available to set wiki")
        return _err("UNAUTHORIZED", "No active wiki session available to set wiki")

    # Prefer the most recently used active session
    def _parse_dt_any(x):
        if isinstance(x, str):
            try:
                s = x.strip()
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    active.sort(key=lambda s: (_parse_dt_any(s.get("last_used_at")) or _parse_dt_any(s.get("updated_at")) or _parse_dt_any(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    target = active[0]
    sid = target.get("id")
    now_iso = _now_iso()

    # Default content model must remain valid; keep existing if valid else set to wikitext.
    dcm = target.get("default_content_model")
    if dcm not in ("wikitext", "json", "css", "javascript", "text", "Scribunto"):
        dcm = "wikitext"

    updated = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["wiki_base_url"] = wiki_base_url
            s["wiki_article_path"] = article_path
            s["wiki_api_endpoint"] = api_endpoint
            s["wiki_rest_endpoint"] = rest_endpoint
            s["default_content_model"] = dcm
            # lifecycle: remains active
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            if s.get("created_at") is None:
                s["created_at"] = now_iso
            updated = True
            target = s
            break

    if not updated:
        _append_request_log("error", "NOT_FOUND", "Active session not found to update")
        return _err("NOT_FOUND", "Active session not found to update")

    _save("wiki_sessions.json", sessions)
    _append_request_log("ok", session_id=sid, wiki_base_url=wiki_base_url, meta={"mode": "byUrl"})
    return {"session": target}

def update_page(title, source, latestId, comment=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "update-page"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        fname = None
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        rid = f"mws_req_{int(time.time()*1000)}_{int(time.time_ns()%1000000)}"
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": now_iso, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save(fname, logs)

    def _dt(v):
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _pick_session_for_title(sessions, pages, title_str):
        # Choose an active session whose wiki_base_url contains a matching page for this title.
        cand = []
        for s in sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            w = s.get("wiki_base_url")
            if not isinstance(w, str) or not w:
                continue
            if any(isinstance(p, dict) and p.get("wiki_base_url") == w and p.get("prefixed_title") == title_str for p in pages):
                cand.append(s)
        if not cand:
            # fallback: any active session (but only if there exists any active at all)
            for s in sessions:
                if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url"):
                    cand.append(s)
        if not cand:
            return None
        cand.sort(key=lambda s: (_dt(s.get("last_used_at")) or _dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        return cand[0]

    def _next_id(prefix, rows):
        best_ts = int(time.time() * 1000)
        suffix = f"{best_ts:x}{int(time.time_ns()%1_000_000):06x}"
        return f"{prefix}_{suffix}"

    def _num_equal(a, b):
        # optimistic concurrency compares numeric ids; accept ints/floats with same numeric value.
        try:
            if a is None or b is None:
                return False
            if isinstance(a, bool) or isinstance(b, bool):
                return False
            return float(a) == float(b)
        except Exception:
            return False

    # Validate inputs
    if not isinstance(title, str) or not title.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "title is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not isinstance(source, str) or not source.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "source is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "source is required and must be a non-empty string")
    if isinstance(latestId, bool) or latestId is None or not isinstance(latestId, (int, float)):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "latestId is required and must be a number"})
        return _err("VALIDATION_ERROR", "latestId is required and must be a number")
    if isinstance(latestId, float):
        if latestId != latestId or latestId in (float("inf"), float("-inf")):
            _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "latestId must be a finite number"})
            return _err("VALIDATION_ERROR", "latestId must be a finite number")
    if comment is not None and not isinstance(comment, str):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "comment must be a string when provided"})
        return _err("VALIDATION_ERROR", "comment must be a string when provided")

    sessions = _load("wiki_sessions.json")
    pages = _load("pages.json")
    revisions = _load("revisions.json")

    # Authenticate ambiently by selecting a workable active session.
    session = _pick_session_for_title(sessions, pages, title.strip())
    if session is None:
        _append_request_log("error", error={"code": "UNAUTHORIZED", "message": "No active wiki session available"})
        return _err("UNAUTHORIZED", "No active wiki session available")

    wiki_base_url = session.get("wiki_base_url")
    session_id = session.get("id")

    # Rate/quota enforcement (if request log exists with rules). Minimal: if a usage/quota file exists, enforce its fields.
    # (No such collection declared; do not invent hard limits.)

    # Resolve page within selected wiki_base_url by pages.prefixed_title
    target_title = title.strip()
    page = None
    for p in pages:
        if isinstance(p, dict) and p.get("wiki_base_url") == wiki_base_url and p.get("prefixed_title") == target_title:
            page = p
            break

    if page is None:
        # If the selected session doesn't have the page, search for another active session that does.
        alt = None
        for s in sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            w = s.get("wiki_base_url")
            if not isinstance(w, str) or not w:
                continue
            for p in pages:
                if isinstance(p, dict) and p.get("wiki_base_url") == w and p.get("prefixed_title") == target_title:
                    alt = (s, p)
                    break
            if alt:
                break
        if alt:
            session, page = alt
            wiki_base_url = session.get("wiki_base_url")
            session_id = session.get("id")
        else:
            _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "NOT_FOUND", "message": "Page not found on selected wiki"})
            return _err("NOT_FOUND", "Page not found on selected wiki")

    # Deletion semantics
    if page.get("status") == "deleted":
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "NOT_FOUND", "message": "Page is deleted"})
        return _err("NOT_FOUND", "Page is deleted")

    # FK integrity for latest revision
    latest_rev_id = page.get("latest_revision_id")
    latest_rev_num = page.get("latest_revision_number")
    if latest_rev_id is None or latest_rev_num is None:
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Page has no latest revision to update"})
        return _err("CONFLICT", "Page has no latest revision to update")

    # Optimistic concurrency check: latestId must equal pages.latest_revision_number at commit time
    if not _num_equal(latestId, latest_rev_num):
        _append_request_log(
            "error",
            session_id=session_id,
            wiki_base_url=wiki_base_url,
            error={"code": "CONFLICT", "message": "Edit conflict: latestId does not match the page's latest revision id", "expectedLatestId": latest_rev_num},
        )
        return _err("CONFLICT", "Edit conflict: latestId does not match the page's latest revision id", expectedLatestId=latest_rev_num)

    # Find the current latest revision row and validate it's for this page & wiki
    latest_rev = None
    for r in revisions:
        if isinstance(r, dict) and r.get("id") == latest_rev_id:
            latest_rev = r
            break
    if latest_rev is None or latest_rev.get("page_id") != page.get("id") or latest_rev.get("wiki_base_url") != page.get("wiki_base_url"):
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "FK integrity error: page.latest_revision_id is invalid"})
        return _err("CONFLICT", "FK integrity error: page.latest_revision_id is invalid")

    # Content model must match existing page's content_model (business rule says "same content model")
    page_cm = page.get("content_model")
    if not isinstance(page_cm, str) or not page_cm.strip():
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Page has invalid content model"})
        return _err("CONFLICT", "Page has invalid content model")
    if latest_rev.get("content_model") != page_cm:
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Page content model mismatch between page and latest revision"})
        return _err("CONFLICT", "Page content model mismatch between page and latest revision")

    # Compute next revision_number: follow "increments according to upstream semantics"
    # For this datastore we treat revision_number as numeric and increment by 1.
    try:
        next_rev_num = float(latest_rev_num) + 1.0
        if next_rev_num.is_integer():
            next_rev_num = float(int(next_rev_num))
    except Exception:
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Cannot compute next revision number"})
        return _err("CONFLICT", "Cannot compute next revision number")

    # Enforce unique(page_id, revision_number)
    for r in revisions:
        if isinstance(r, dict) and r.get("page_id") == page.get("id") and _num_equal(r.get("revision_number"), next_rev_num):
            # If already exists and has same source, be idempotent-ish? update-page isn't specified idempotent; treat as conflict.
            _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Revision number conflict for page"})
            return _err("CONFLICT", "Revision number conflict for page")

    # Create new revision
    new_rev_id = _next_id("mws_rev", revisions)
    sha1 = hashlib.sha1(source.encode("utf-8")).hexdigest()
    new_rev = {
        "id": new_rev_id,
        "page_id": page.get("id"),
        "wiki_base_url": page.get("wiki_base_url"),
        "revision_number": next_rev_num,
        "parent_revision_number": float(latest_rev_num),
        "status": "published",
        "comment": comment if (isinstance(comment, str) and comment.strip()) else None,
        "content_model": page_cm,
        "source_text": source,
        "sha1": sha1,
        "author_user_id": None,
        "tags": [],
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Transition previous latest revision: published -> superseded allowed
    prev_status = latest_rev.get("status")
    if prev_status == "published":
        latest_rev["status"] = "superseded"
        latest_rev["updated_at"] = now_iso
    elif prev_status in ("superseded", "reverted", "deleted"):
        # If already not published, keep as-is (don't attempt illegal transitions)
        pass
    else:
        # Unknown status -> validation-ish conflict
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "Latest revision has invalid status"})
        return _err("CONFLICT", "Latest revision has invalid status")

    # Update page latest pointers and timestamps; clear rendered html cache because it is now stale
    page["latest_revision_id"] = new_rev_id
    page["latest_revision_number"] = next_rev_num
    page["rendered_html_cache"] = None
    page["rendered_html_revision_id"] = None
    page["updated_at"] = now_iso

    # Persist revisions + pages + session last_used_at
    revisions.append(new_rev)
    _save("revisions.json", revisions)
    _save("pages.json", pages)

    session["last_used_at"] = now_iso
    session["updated_at"] = now_iso
    _save("wiki_sessions.json", sessions)

    # Response: updated page + new latest revision metadata
    resp = {
        "page": {
            "id": page.get("id"),
            "wiki_base_url": page.get("wiki_base_url"),
            "namespace": page.get("namespace"),
            "title": page.get("title"),
            "prefixed_title": page.get("prefixed_title"),
            "content_model": page.get("content_model"),
            "status": page.get("status"),
            "latest_revision_id": page.get("latest_revision_id"),
            "latest_revision_number": page.get("latest_revision_number"),
            "license_code": page.get("license_code"),
            "license_url": page.get("license_url"),
            "created_at": page.get("created_at"),
            "updated_at": page.get("updated_at"),
        },
        "latest_revision": {
            "id": new_rev.get("id"),
            "revision_number": new_rev.get("revision_number"),
            "parent_revision_number": new_rev.get("parent_revision_number"),
            "status": new_rev.get("status"),
            "comment": new_rev.get("comment"),
            "content_model": new_rev.get("content_model"),
            "sha1": new_rev.get("sha1"),
            "tags": new_rev.get("tags"),
            "created_at": new_rev.get("created_at"),
        },
    }
    _append_request_log("ok", session_id=session_id, wiki_base_url=wiki_base_url, meta={"page_id": page.get("id"), "new_revision_id": new_rev_id})
    return resp

def get_file(title, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get-file"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        fname = None
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        rid = f"mws_req_{int(time.time()*1000)}_{int(time.time_ns()%1000000)}"
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": now_iso, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save(fname, logs)

    def _dt(v):
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _pick_active_session_for_title(sessions, pages, files, wanted_title):
        # Prefer sessions where the title can be resolved (as file title, or as a File: page).
        cand = []
        for s in sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            w = s.get("wiki_base_url")
            if not isinstance(w, str) or not w:
                continue
            if any(isinstance(f, dict) and f.get("wiki_base_url") == w and f.get("title") == wanted_title for f in files):
                cand.append(s); continue
            if any(isinstance(p, dict) and p.get("wiki_base_url") == w and p.get("prefixed_title") == wanted_title for p in pages):
                cand.append(s); continue
            # allow callers to pass unprefixed "Foo.png" by matching "File:Foo.png"
            if not wanted_title.lower().startswith("file:"):
                pref = "File:" + wanted_title
                if any(isinstance(p, dict) and p.get("wiki_base_url") == w and p.get("prefixed_title") == pref for p in pages):
                    cand.append(s); continue
                if any(isinstance(f, dict) and f.get("wiki_base_url") == w and f.get("title") == pref for f in files):
                    cand.append(s); continue
        if not cand:
            for s in sessions:
                if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url"):
                    cand.append(s)
        if not cand:
            return None
        cand.sort(key=lambda s: (_dt(s.get("last_used_at")) or _dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        return cand[0]

    if not isinstance(title, str) or not title.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "title is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")

    wanted_title = title.strip()
    sessions = _load("wiki_sessions.json")
    pages = _load("pages.json")
    files = _load("files.json")

    session = _pick_active_session_for_title(sessions, pages, files, wanted_title)
    if session is None:
        _append_request_log("error", error={"code": "UNAUTHORIZED", "message": "No active wiki session available"})
        return _err("UNAUTHORIZED", "No active wiki session available")

    wiki_base_url = session.get("wiki_base_url")
    session_id = session.get("id")

    # Resolve file title: try exact, then File: prefix if absent
    candidate_titles = [wanted_title]
    if not wanted_title.lower().startswith("file:"):
        candidate_titles.append("File:" + wanted_title)

    # Find an existing file row first
    file_row = None
    for t in candidate_titles:
        for f in files:
            if isinstance(f, dict) and f.get("wiki_base_url") == wiki_base_url and f.get("title") == t:
                file_row = f
                break
        if file_row:
            break

    # If no file row, but a File namespace page exists, return a synthetic "missing" view without persisting new rows.
    # (Business rule: refresh job may populate files; until then return status='missing'.)
    page_row = None
    if file_row is None:
        for t in candidate_titles:
            for p in pages:
                if isinstance(p, dict) and p.get("wiki_base_url") == wiki_base_url and p.get("prefixed_title") == t and p.get("namespace") == 6:
                    page_row = p
                    break
            if page_row:
                break
        if page_row is None:
            # As with other tools, avoid choosing a bad session: search any active session that can satisfy the title.
            alt = None
            for s in sessions:
                if not isinstance(s, dict) or s.get("status") != "active":
                    continue
                w = s.get("wiki_base_url")
                if not isinstance(w, str) or not w:
                    continue
                for t in candidate_titles:
                    for f in files:
                        if isinstance(f, dict) and f.get("wiki_base_url") == w and f.get("title") == t:
                            alt = (s, f, None)
                            break
                    if alt:
                        break
                    for p in pages:
                        if isinstance(p, dict) and p.get("wiki_base_url") == w and p.get("prefixed_title") == t and p.get("namespace") == 6:
                            alt = (s, None, p)
                            break
                    if alt:
                        break
                if alt:
                    break
            if alt:
                session, file_row, page_row = alt
                wiki_base_url = session.get("wiki_base_url")
                session_id = session.get("id")
            else:
                _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "NOT_FOUND", "message": "File not found"})
                return _err("NOT_FOUND", "File not found")

    # Update session last_used_at
    session["last_used_at"] = now_iso
    session["updated_at"] = now_iso
    _save("wiki_sessions.json", sessions)

    if file_row is None and page_row is not None:
        resp = {
            "file": {
                "id": None,
                "wiki_base_url": wiki_base_url,
                "page_id": page_row.get("id"),
                "title": page_row.get("prefixed_title"),
                "status": "missing",
                "mime_type": None,
                "size_bytes": None,
                "width": None,
                "height": None,
                "original_url": None,
                "thumbnail_url": None,
                "preview_url": None,
                "sha1": None,
                "created_at": None,
                "updated_at": None,
            }
        }
        _append_request_log("ok", session_id=session_id, wiki_base_url=wiki_base_url, meta={"page_id": page_row.get("id"), "status": "missing"})
        return resp

    # Validate FK: file.page_id exists & same wiki_base_url
    page_id = file_row.get("page_id")
    page = None
    for p in pages:
        if isinstance(p, dict) and p.get("id") == page_id:
            page = p
            break
    if page is None or page.get("wiki_base_url") != file_row.get("wiki_base_url"):
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "FK integrity error: file.page_id is invalid"})
        return _err("CONFLICT", "FK integrity error: file.page_id is invalid")

    resp = {
        "file": {
            "id": file_row.get("id"),
            "wiki_base_url": file_row.get("wiki_base_url"),
            "page_id": file_row.get("page_id"),
            "title": file_row.get("title"),
            "status": file_row.get("status"),
            "mime_type": file_row.get("mime_type"),
            "size_bytes": file_row.get("size_bytes"),
            "width": file_row.get("width"),
            "height": file_row.get("height"),
            "original_url": file_row.get("original_url"),
            "thumbnail_url": file_row.get("thumbnail_url"),
            "preview_url": file_row.get("preview_url"),
            "sha1": file_row.get("sha1"),
            "created_at": file_row.get("created_at"),
            "updated_at": file_row.get("updated_at"),
        }
    }
    _append_request_log("ok", session_id=session_id, wiki_base_url=wiki_base_url, meta={"file_id": file_row.get("id")})
    return resp

def create_page(source, title, comment=None, contentModel=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "create-page"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        ts = _now_iso()
        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta:
            row["meta"] = meta
        if error:
            row["error"] = error
        logs.append(row)
        _save(chosen, logs)

    # Validate
    if not isinstance(title, str) or not title.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "title is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not isinstance(source, str) or not source.strip():
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "source is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "source is required and must be a non-empty string")
    if comment is not None and not isinstance(comment, str):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "comment must be a string when provided"})
        return _err("VALIDATION_ERROR", "comment must be a string when provided")
    if contentModel is not None and not isinstance(contentModel, str):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "contentModel must be a string when provided"})
        return _err("VALIDATION_ERROR", "contentModel must be a string when provided")

    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    revisions = _load("revisions.json")
    if not isinstance(revisions, list):
        revisions = []
    title_q = title.strip()

    # Choose an active session; if multiple, pick one with a coherent wiki_base_url
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url")]
    if not active_sessions:
        _append_request_log("error", error={"code": "UNAUTHORIZED", "message": "No wiki selected for session"})
        return _err("UNAUTHORIZED", "No wiki selected for session")

    # Prefer a session whose wiki does not already contain this page
    chosen_session = None
    for s in active_sessions:
        wbu = s.get("wiki_base_url")
        exists = False
        for p in pages:
            if isinstance(p, dict) and p.get("wiki_base_url") == wbu and p.get("prefixed_title") == title_q:
                exists = True
                break
        if not exists:
            chosen_session = s
            break
    if chosen_session is None:
        # all active sessions already have the page => conflict on whichever wiki is selected; report conflict
        any_wbu = active_sessions[0].get("wiki_base_url")
        _append_request_log("error", session_id=active_sessions[0].get("id"), wiki_base_url=any_wbu,
                            error={"code": "CONFLICT", "message": "A page with the same title already exists on the selected wiki"})
        return _err("CONFLICT", "A page with the same title already exists on the selected wiki")

    wbu = chosen_session.get("wiki_base_url")

    # Determine content model: if omitted, use session default; if provided but looks like a session id, treat as omitted
    allowed_models = {"wikitext", "json", "css", "javascript", "text", "Scribunto"}
    cm = contentModel.strip() if isinstance(contentModel, str) else None
    if cm and re.match(r"^mws_sess_", cm):
        cm = None
    if not cm:
        cm = chosen_session.get("default_content_model") or "wikitext"
    if not isinstance(cm, str) or cm not in allowed_models:
        _append_request_log("error", session_id=chosen_session.get("id"), wiki_base_url=wbu,
                            error={"code": "VALIDATION_ERROR", "message": "contentModel is invalid; must be one of: wikitext, json, css, javascript, text, Scribunto"})
        return _err("VALIDATION_ERROR", "contentModel is invalid; must be one of: wikitext, json, css, javascript, text, Scribunto")

    # Ensure unique(wiki_base_url, prefixed_title)
    for p in pages:
        if isinstance(p, dict) and p.get("wiki_base_url") == wbu and p.get("prefixed_title") == title_q:
            _append_request_log("error", session_id=chosen_session.get("id"), wiki_base_url=wbu,
                                error={"code": "CONFLICT", "message": "A page with the same title already exists on the selected wiki"})
            return _err("CONFLICT", "A page with the same title already exists on the selected wiki")

    # Create page + initial revision
    now = _now_iso()
    page_id = "mws_page_" + hashlib.sha1((wbu + "|" + title_q + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
    existing_page_ids = {p.get("id") for p in pages if isinstance(p, dict)}
    if page_id in existing_page_ids:
        page_id = "mws_page_" + hashlib.sha1((wbu + "|" + title_q + "|" + now + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]

    # Namespace inference: if "File:" then ns=6 else 0
    namespace = 6 if title_q.startswith("File:") else 0
    # crude title and prefixed_title: store as provided
    page_row = {
        "id": page_id,
        "wiki_base_url": wbu,
        "namespace": namespace,
        "title": title_q.split(":", 1)[1] if namespace == 6 and ":" in title_q else title_q,
        "prefixed_title": title_q,
        "content_model": cm,
        "status": "active",
        "latest_revision_id": None,
        "latest_revision_number": None,
        "license_code": None,
        "license_url": None,
        "rendered_html_cache": None,
        "rendered_html_revision_id": None,
        "search_vector": None,
        "created_at": now,
        "updated_at": now,
    }

    # Determine initial revision_number (>0) unique on (page_id, revision_number)
    new_revnum = 1.0
    rev_id = "mws_rev_" + hashlib.sha1((page_id + "|1|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
    existing_rev_ids = {r.get("id") for r in revisions if isinstance(r, dict)}
    if rev_id in existing_rev_ids:
        rev_id = "mws_rev_" + hashlib.sha1((page_id + "|1|" + now + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]

    rev_row = {
        "id": rev_id,
        "page_id": page_id,
        "wiki_base_url": wbu,
        "revision_number": new_revnum,
        "parent_revision_number": None,
        "status": "published",
        "comment": comment,
        "content_model": cm,
        "source_text": source,
        "sha1": hashlib.sha1(source.encode("utf-8")).hexdigest(),
        "author_user_id": None,
        "tags": [],
        "created_at": now,
        "updated_at": now,
    }

    page_row["latest_revision_id"] = rev_id
    page_row["latest_revision_number"] = new_revnum

    pages.append(page_row)
    revisions.append(rev_row)
    _save("pages.json", pages)
    _save("revisions.json", revisions)

    # Touch session
    sessions2 = _load("wiki_sessions.json")
    if isinstance(sessions2, list):
        for s2 in sessions2:
            if isinstance(s2, dict) and s2.get("id") == chosen_session.get("id"):
                s2["last_used_at"] = now
                s2["updated_at"] = now
                break
        _save("wiki_sessions.json", sessions2)

    _append_request_log("ok", session_id=chosen_session.get("id"), wiki_base_url=wbu)
    return {
        "page": {
            "id": page_row.get("id"),
            "wiki_base_url": page_row.get("wiki_base_url"),
            "namespace": page_row.get("namespace"),
            "title": page_row.get("title"),
            "prefixed_title": page_row.get("prefixed_title"),
            "content_model": page_row.get("content_model"),
            "status": page_row.get("status"),
            "license_code": page_row.get("license_code"),
            "license_url": page_row.get("license_url"),
            "latest_revision_number": page_row.get("latest_revision_number"),
            "latest_revision": {
                "id": rev_row.get("id"),
                "revision_number": rev_row.get("revision_number"),
                "parent_revision_number": rev_row.get("parent_revision_number"),
                "status": rev_row.get("status"),
                "comment": rev_row.get("comment"),
                "tags": rev_row.get("tags"),
                "created_at": rev_row.get("created_at"),
                "updated_at": rev_row.get("updated_at"),
                "content_model": rev_row.get("content_model"),
            },
            "created_at": page_row.get("created_at"),
            "updated_at": page_row.get("updated_at"),
        }
    }

def get_session(sessionId=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    sessions = _load("wiki_sessions.json")
    if not sessions:
        return _err("UNAUTHORIZED", "No wiki session is present")

    def _parse_dt(x):
        try:
            if isinstance(x, str) and x.endswith("Z"):
                return datetime.datetime.fromisoformat(x[:-1])
            if isinstance(x, str):
                return datetime.datetime.fromisoformat(x)
        except Exception:
            return None
        return None

    target = None
    if sessionId is not None:
        if not isinstance(sessionId, str) or not sessionId.strip():
            return _err("VALIDATION_ERROR", "sessionId must be a non-empty string when provided")
        sid = sessionId.strip()
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                target = s
                break
        if not target:
            return _err("NOT_FOUND", "Unknown session id")
    else:
        # Ambient: return caller's current session by selecting the most recently used active one,
        # otherwise the most recently used overall.
        active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        pool = active if active else [s for s in sessions if isinstance(s, dict)]
        if not pool:
            return _err("UNAUTHORIZED", "No wiki session is present")
        pool.sort(key=lambda s: (_parse_dt(s.get("last_used_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min), reverse=True)
        target = pool[0]

    # If a specific session is requested, "Refuses with UNAUTHORIZED if no session is present" already handled.
    # Update last_used_at only for active sessions (since other tools require active to be used)
    changed = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == target.get("id"):
            if s.get("status") == "active":
                s["last_used_at"] = now
                s["updated_at"] = now
                changed = True
            target = s
            break
    if changed:
        _save("wiki_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "session": {
            "id": target.get("id"),
            "status": target.get("status"),
            "wiki_base_url": target.get("wiki_base_url"),
            "wiki_article_path": target.get("wiki_article_path"),
            "wiki_api_endpoint": target.get("wiki_api_endpoint"),
            "wiki_rest_endpoint": target.get("wiki_rest_endpoint"),
            "default_content_model": target.get("default_content_model"),
            "last_used_at": target.get("last_used_at"),
            "created_at": target.get("created_at"),
            "updated_at": target.get("updated_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }

def revoke_session(sessionId, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, session_id=None, error_code=None):
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "session_id": session_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(sessionId, str) or not sessionId:
        _log("revoke-session", "error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string.")
    if reason is not None and not isinstance(reason, str):
        _log("revoke-session", "error", sessionId, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided.")

    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    idx = None
    sess = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sessionId:
            idx = i
            sess = s
            break

    if sess is None:
        _log("revoke-session", "error", sessionId, "NOT_FOUND")
        return _err("NOT_FOUND", "Session does not exist.", sessionId=sessionId)

    # Enforce lifecycle transition: only active -> revoked allowed for this endpoint.
    if sess.get("status") != "active":
        _log("revoke-session", "error", sessionId, "CONFLICT")
        return _err("CONFLICT", "Session is not active and cannot be revoked.", status=sess.get("status"))

    # Perform transition
    sess["status"] = "revoked"
    sess["updated_at"] = now
    sess["last_used_at"] = now

    # Optional auditing note (schema doesn't include it; store in a best-effort sidecar field)
    if reason:
        # keep a small audit trail array
        trail = sess.get("audit_trail")
        if not isinstance(trail, list):
            trail = []
        trail.append({"at": now, "action": "revoke-session", "reason": reason})
        sess["audit_trail"] = trail

    sessions[idx] = sess
    _save("wiki_sessions.json", sessions)

    resp = {
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "wiki_base_url": sess.get("wiki_base_url"),
            "wiki_article_path": sess.get("wiki_article_path"),
            "wiki_api_endpoint": sess.get("wiki_api_endpoint"),
            "wiki_rest_endpoint": sess.get("wiki_rest_endpoint"),
            "default_content_model": sess.get("default_content_model"),
            "last_used_at": sess.get("last_used_at"),
            "created_at": sess.get("created_at"),
            "updated_at": sess.get("updated_at"),
        }
    }
    _log("revoke-session", "ok", sessionId, None)
    return resp

