        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(chosen, logs)

    if not isinstance(sessionId, str) or not sessionId.strip():
        _append_request_log("error", "VALIDATION_ERROR", "sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")
    sessionId = sessionId.strip()

    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if not sess:
        _append_request_log("error", "NOT_FOUND", "Session not found", session_id=sessionId)
        return _err("NOT_FOUND", "Session not found")

    if sess.get("status") != "active":
        _append_request_log("error", "CONFLICT", "Session is not active", session_id=sessionId, wiki_base_url=sess.get("wiki_base_url"))
        return _err("CONFLICT", "Session is not active")

    # Lifecycle transition active -> expired only
    now_iso = _now_iso()
    updated = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            s["status"] = "expired"
            s["updated_at"] = now_iso
            # last_used_at must be >= created_at; do not move backwards
            if s.get("last_used_at") is None:
                s["last_used_at"] = now_iso
            updated = True
            sess = s
            break

    if not updated:
        _append_request_log("error", "NOT_FOUND", "Session not found", session_id=sessionId)
        return _err("NOT_FOUND", "Session not found")

    _save("wiki_sessions.json", sessions)
    _append_request_log("ok", session_id=sessionId, wiki_base_url=sess.get("wiki_base_url"))
    return {"session": sess}

def list_pages(namespace=None, status=None, titlePrefix=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "list-pages"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            if x.tzinfo is None:
                return x.replace(tzinfo=datetime.timezone.utc)
            return x.astimezone(datetime.timezone.utc)
        if isinstance(x, (int, float)):
            return datetime.datetime.fromtimestamp(float(x), tz=datetime.timezone.utc)
        if isinstance(x, str):
            try:
                s = x.strip()
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _append_request_log(status_s, error_code=None, error_message=None, session_id=None, wiki_base_url=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        ts = _now_iso()
        log_candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json"]
        chosen = None
        for fname in log_candidates:
            if os.path.exists(os.path.join(_DB, fname)):
                chosen = fname
                break
        if chosen is None:
            chosen = "request_logs.json"
        logs = _load(chosen)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha1((endpoint + "|" + ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24]
        row = {"id": rid, "endpoint": endpoint, "status": status_s, "timestamp": ts, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(chosen, logs)

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        return json.loads(raw.decode("utf-8"))

    # Validate
    if namespace is not None and not isinstance(namespace, int):
        _append_request_log("error", "VALIDATION_ERROR", "namespace must be an integer when provided")
        return _err("VALIDATION_ERROR", "namespace must be an integer when provided")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "protected", "moved"):
            _append_request_log("error", "VALIDATION_ERROR", "status must be one of active, deleted, protected, moved")
            return _err("VALIDATION_ERROR", "status must be one of active, deleted, protected, moved")
    if titlePrefix is not None and (not isinstance(titlePrefix, str)):
        _append_request_log("error", "VALIDATION_ERROR", "titlePrefix must be a string when provided")
        return _err("VALIDATION_ERROR", "titlePrefix must be a string when provided")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _append_request_log("error", "VALIDATION_ERROR", "limit must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if order is None:
        order = "updatedAtDesc"
    if not isinstance(order, str) or order not in ("updatedAtDesc", "updatedAtAsc", "titleAsc", "titleDesc"):
        _append_request_log("error", "VALIDATION_ERROR", "order must be one of updatedAtDesc, updatedAtAsc, titleAsc, titleDesc")
        return _err("VALIDATION_ERROR", "order must be one of updatedAtDesc, updatedAtAsc, titleAsc, titleDesc")
    if cursor is not None and not isinstance(cursor, str):
        _append_request_log("error", "VALIDATION_ERROR", "cursor must be a string when provided")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    # Resolve active session (selected wiki)
    sessions = _load("wiki_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url").strip()]
    if not candidates:
        _append_request_log("error", "UNAUTHORIZED", "No active wiki session selected")
        return _err("UNAUTHORIZED", "No active wiki session selected")

    candidates.sort(key=lambda s: (_parse_dt_any(s.get("last_used_at")) or _parse_dt_any(s.get("updated_at")) or _parse_dt_any(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    sess = candidates[0]
    wiki_base_url = sess.get("wiki_base_url")
    session_id = sess.get("id")

    # touch session last_used_at
    now_iso = _now_iso()
    if isinstance(session_id, str):
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                s["last_used_at"] = now_iso
                s["updated_at"] = now_iso
                break
        _save("wiki_sessions.json", sessions)

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []

    rows = [p for p in pages if isinstance(p, dict) and p.get("wiki_base_url") == wiki_base_url]

    if namespace is not None:
        rows = [p for p in rows if p.get("namespace") == namespace]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if titlePrefix is not None and titlePrefix != "":
        rows = [p for p in rows if isinstance(p.get("prefixed_title"), str) and p.get("prefixed_title").startswith(titlePrefix)]

    # Sorting
    def sort_key(p):
        if order.startswith("updatedAt"):
            dt = _parse_dt_any(p.get("updated_at")) or _parse_dt_any(p.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        else:
            return p.get("prefixed_title") or ""

    reverse = (order in ("updatedAtDesc", "titleDesc"))
    rows.sort(key=sort_key, reverse=reverse)

    # Cursor pagination: cursor encodes an offset integer and a hash of filters to avoid cross-query reuse.
    offset = 0
    if cursor:
        try:
            payload = _b64d(cursor)
            if isinstance(payload, dict) and isinstance(payload.get("offset"), int) and payload.get("offset") >= 0:
                offset = payload["offset"]
        except Exception:
            _append_request_log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(rows)
    page_rows = rows[offset:offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = _b64e({"offset": next_offset}) if has_more else None

    out = []
    for p in page_rows:
        out.append({
            "id": p.get("id"),
            "wiki_base_url": p.get("wiki_base_url"),
            "namespace": p.get("namespace"),
            "title": p.get("title"),
            "prefixed_title": p.get("prefixed_title"),
            "content_model": p.get("content_model"),
            "status": p.get("status"),
            "latest_revision_id": p.get("latest_revision_id"),
            "latest_revision_number": p.get("latest_revision_number"),
            "license_code": p.get("license_code"),
            "license_url": p.get("license_url"),
            "created_at": p.get("created_at"),
            "updated_at": p.get("updated_at"),
        })

    resp = {"pages": out, "meta": {"total": total, "count": len(out), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _append_request_log("ok", session_id=session_id, wiki_base_url=wiki_base_url, meta={"count": len(out), "total": total})
    return resp

def get_revision(id, includeSource=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0071000" if __import__("os").path.isdir("./environment_mix/0071000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get-revision"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _append_request_log(status, session_id=None, wiki_base_url=None, error=None, meta=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        fname = None
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        rid = f"mws_req_{int(time.time()*1000)}_{int(time.time_ns()%1000000)}"
        row = {"id": rid, "endpoint": endpoint, "status": status, "timestamp": now_iso, "latency_ms": latency_ms}
        if session_id is not None:
            row["session_id"] = session_id
        if wiki_base_url is not None:
            row["wiki_base_url"] = wiki_base_url
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save(fname, logs)

    def _dt(v):
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _pick_active_session_for_revision(sessions, revisions, rev_id_str):
        # Prefer sessions whose wiki_base_url contains the revision.
        cand = []
        for s in sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            w = s.get("wiki_base_url")
            if not isinstance(w, str) or not w:
                continue
            if any(isinstance(r, dict) and r.get("id") == rev_id_str and r.get("wiki_base_url") == w for r in revisions):
                cand.append(s)
        if not cand:
            for s in sessions:
                if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("wiki_base_url"), str) and s.get("wiki_base_url"):
                    cand.append(s)
        if not cand:
            return None
        cand.sort(key=lambda s: (_dt(s.get("last_used_at")) or _dt(s.get("updated_at")) or _dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        return cand[0]

    if includeSource is None:
        includeSource = False
    if not isinstance(includeSource, bool):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "includeSource must be a boolean when provided"})
        return _err("VALIDATION_ERROR", "includeSource must be a boolean when provided")

    # id is specified as number in schema; accept ints/floats that map to our string ids by searching.
    if id is None or isinstance(id, bool) or not isinstance(id, (int, float)):
        _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "id is required and must be a number"})
        return _err("VALIDATION_ERROR", "id is required and must be a number")
    if isinstance(id, float):
        if id != id or id in (float("inf"), float("-inf")):
            _append_request_log("error", error={"code": "VALIDATION_ERROR", "message": "id must be a finite number"})
            return _err("VALIDATION_ERROR", "id must be a finite number")

    # Convert numeric id to candidate strings: "5" and "5.0" etc.
    # The audit shows calls like id=5.0; prior broken code likely treated it as revision_number.
    # Real behavior: tool says "Fetches a single revision by id" so we attempt:
    # 1) match revisions.id exactly if it is numeric-like stored (unlikely)
    # 2) else treat provided id as revision_number and find within selected wiki (common in integrations)
    requested_num = float(id)
    id_variants = []
    if requested_num.is_integer():
        id_variants.append(str(int(requested_num)))
        id_variants.append(f"{int(requested_num)}.0")
    id_variants.append(str(requested_num))

    sessions = _load("wiki_sessions.json")
    pages = _load("pages.json")
    revisions = _load("revisions.json")

    # Pick workable session
    session = _pick_active_session_for_revision(sessions, revisions, id_variants[0] if id_variants else str(id))
    if session is None:
        _append_request_log("error", error={"code": "UNAUTHORIZED", "message": "No active wiki session available"})
        return _err("UNAUTHORIZED", "No active wiki session available")
    wiki_base_url = session.get("wiki_base_url")
    session_id = session.get("id")

    # Find revision:
    rev = None
    # First: match by revisions.id if any row has that id (rare)
    for v in id_variants:
        for r in revisions:
            if isinstance(r, dict) and r.get("wiki_base_url") == wiki_base_url and r.get("id") == v:
                rev = r
                break
        if rev:
            break
    # Second: match by revisions.revision_number equals requested numeric
    if rev is None:
        for r in revisions:
            if not isinstance(r, dict):
                continue
            if r.get("wiki_base_url") != wiki_base_url:
                continue
            try:
                if float(r.get("revision_number")) == requested_num:
                    rev = r
                    break
            except Exception:
                continue

    # If not found under selected wiki, search other active sessions (fix "picked wrong context" defect)
    if rev is None:
        alt = None
        for s in sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            w = s.get("wiki_base_url")
            if not isinstance(w, str) or not w:
                continue
            for r in revisions:
                if not isinstance(r, dict) or r.get("wiki_base_url") != w:
                    continue
                matched = False
                for v in id_variants:
                    if r.get("id") == v:
                        matched = True
                        break
                if not matched:
                    try:
                        matched = float(r.get("revision_number")) == requested_num
                    except Exception:
                        matched = False
                if matched:
                    alt = (s, r)
                    break
            if alt:
                break
        if alt:
            session, rev = alt
            wiki_base_url = session.get("wiki_base_url")
            session_id = session.get("id")

    if rev is None:
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "NOT_FOUND", "message": "Revision not found"})
        return _err("NOT_FOUND", "Revision not found")

    # FK integrity: page exists and matches wiki_base_url
    page = None
    for p in pages:
        if isinstance(p, dict) and p.get("id") == rev.get("page_id"):
            page = p
            break
    if page is None or page.get("wiki_base_url") != rev.get("wiki_base_url"):
        _append_request_log("error", session_id=session_id, wiki_base_url=wiki_base_url, error={"code": "CONFLICT", "message": "FK integrity error: revisions.page_id is invalid"})
        return _err("CONFLICT", "FK integrity error: revisions.page_id is invalid")

    # Update session last_used_at
    session["last_used_at"] = now_iso
    session["updated_at"] = now_iso
    _save("wiki_sessions.json", sessions)

    out = {
        "revision": {
            "id": rev.get("id"),
            "page_id": rev.get("page_id"),
            "wiki_base_url": rev.get("wiki_base_url"),
            "revision_number": rev.get("revision_number"),
            "parent_revision_number": rev.get("parent_revision_number"),
            "status": rev.get("status"),
            "comment": rev.get("comment"),
            "content_model": rev.get("content_model"),
            "sha1": rev.get("sha1"),
            "author_user_id": rev.get("author_user_id"),
            "tags": rev.get("tags"),
            "created_at": rev.get("created_at"),
            "updated_at": rev.get("updated_at"),
        }
    }
    if includeSource:
        out["revision"]["source_text"] = rev.get("source_text")

    _append_request_log("ok", session_id=session_id, wiki_base_url=wiki_base_url, meta={"revision_id": rev.get("id"), "includeSource": includeSource})
    return out
